package per.chowh.bot.utils;import lombok.extern.slf4j.Slf4j;import okhttp3.OkHttpClient;import per.chowh.bot.config.ChowhBotConfig;import java.io.IOException;import java.net.InetSocketAddress;import java.net.Proxy;import java.time.Duration;/** * @author : Chowhound * @since : 2025/10/21 - 14:46 */@Slf4jpublic class HttpProxyUtils{    private static OkHttpClient BASE_CLIENT;    static {        String host = ChowhBotConfig.getConfig("per.network.proxy.host");        String port = ChowhBotConfig.getConfig("per.network.proxy.port");        if (host != null && port != null) {            Proxy proxy = new Proxy(Proxy.Type.HTTP, new InetSocketAddress(host, Integer.parseInt(port)));            BASE_CLIENT = new OkHttpClient.Builder()                    .proxy(proxy)                    .callTimeout(Duration.ofSeconds(60))                    .connectTimeout(Duration.ofSeconds(60))                    .readTimeout(Duration.ofSeconds(60))                    .writeTimeout(Duration.ofSeconds(60))                    .build();            log.info("HttpProxyUtils代理地址 host: {}, port: {}",  host, port);        }    }    public static String doGetStr(String url) throws IOException {        return HttpUtils.doGetStr(BASE_CLIENT, url, null);    }    public static byte[] doGetBytes(String url) throws IOException {        return HttpUtils.doGetBytes(BASE_CLIENT, url, null);    }}